// One-comparator stage, based on a multi-comparator Pythagorean
// triangle (a <= b <= c <= d). The stage finds the minimum among the
// first three inputs, ignoring the fourth.
module one_comp_stage (
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    output reg [7:0] min
);
    reg [7:0] t0;
    reg [7:0] t1;
    always @* begin
        if (a <= b) begin
            t0 = a;
            if (b <= c) t1 = b;
            else        t1 = c;
        end
        else begin
            t0 = b;
            if (a <= c) t1 = a;
            else        t1 = c;
        end
        if (t0 <= t1) min = t0;
        else          min = t1;
    end
endmodule

